-- Peru deep-dive content: page, stats, file_format cards,
-- scope_transmission cards + lifecycle card ("The clearance flow"),
-- steps, penalties_related cards, portal. No penalty rows/table.

INSERT OR IGNORE INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Centralised clearance (SUNAT / OSE)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. OSE/PSE requirements, business validation rules, and sector-specific reporting continue to evolve — confirm current requirements directly with SUNAT before building an integration.', 'Peru''s rollout followed the classic Latin American pattern — largest taxpayers first, then a steady widening until essentially the entire economy was covered.', 'CPE is a broad umbrella term — Peru covers far more document types under this single framework than most countries in this tracker.', 'Peru''s model has a genuinely distinctive feature: OSEs aren''t mere intermediaries — they carry the same legal validation authority as SUNAT itself.', 'Verifying your provider''s authorisation status matters more here than in most countries — unauthorised PSE/OSE providers issue documents with no legal validity at all.', 'Peru''s e-invoicing and e-reporting framework is described by practitioners as comprehensive and technologically advanced — the practical risk is invalidity, not just fines.' FROM countries WHERE name_en = 'Peru';

