INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Format', '[["Syntax", "UBL 2.1 XML, exclusively since March 2019"], ["Encoding", "UTF-8"], ["Signature standard", "X.509 v3"], ["Integrity", "SHA-256 hash"]]', 'Article 2 of the implementing regulation is explicit: only documents meeting all these technical characteristics simultaneously are legally valid — partial compliance doesn''t count.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'CPE document family', '[["Sales", "Invoices, boletas de venta"], ["Adjustments", "Credit and debit notes"], ["Tax-related", "Withholding and perception vouchers"], ["Other", "Public service receipts, electronic purchase settlements, GRE (dispatch/transport guides)"]]', 'Choosing the correct CPE type for your specific transaction is critical — the wrong type can undermine your ability to deduct expenses or claim tax credits, not just create a paperwork headache.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Document naming', '[["Examples", "\"Factura Electrónica\", \"Boleta de Venta Electrónica\""]]', 'These are formal, specific document names defined in regulation — get the label as well as the content right.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Archiving', '[["Retention period", "5 years minimum, from the first day of the following year"], ["What to keep", "XML, CDR, rejection notices, daily summaries"]]', 'The exact retention obligation varies slightly by taxpayer regime — confirm your specific rule rather than assuming a flat 5-year figure applies uniformly.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Peru' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'The three roles', '[["PSE", "Optional — builds and signs the XML on the taxpayer''s behalf"], ["OSE", "Validates the CPE with the same legal authority as SUNAT — not a mere go-between"], ["SEE", "SUNAT''s own direct electronic issuance system"]]', 'This is worth internalising: an OSE''s validation is legally equivalent to SUNAT validating it directly. But an OSE cannot validate delivery/transport documents — that distinction matters for logistics-heavy businesses.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Peru' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Choosing your operating tier', '[["SEE-SOL", "Low volume (<1,000/month), free web portal"], ["PSE", "Medium volume, external facilitation"], ["OSE", "High volume, own ERP integration"], ["SEE Facturador", "Businesses without in-house technical development capacity"]]', 'Match your tier to your actual transaction volume and technical capacity — over-engineering a low-volume business onto a full OSE integration wastes effort that a free SOL portal account would have covered.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Peru' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'A permitted but risky shortcut', '[["Asynchronous delivery", "Technically allowed — sending to the buyer before SUNAT/OSE validation"], ["Risk", "Explicitly flagged as risky practice by practitioners"]]', 'Just because the regulation permits sending an invoice before validation completes doesn''t make it good practice — a subsequently rejected document creates real reconciliation problems for both parties.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Peru' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

