INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Obtain your RUC and register as an electronic issuer', 'Your Registro Único de Contribuyentes number and electronic-issuer registration with SUNAT are the prerequisites for everything that follows.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Peru' AND ds.sort_order = 0;
