INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Choose your operating tier based on volume', 'SEE-SOL for low volume, PSE for medium volume with external help, OSE for high volume with your own ERP, or SEE Facturador if you lack in-house development capacity.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Peru' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Peru';
