INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Build a CDR storage and reconciliation workflow', 'Every issued CPE needs its corresponding CDR retained alongside it — treat the pair as a single compliance record, not two separate files.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Peru' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 6 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Avoid asynchronous delivery shortcuts', 'Wait for SUNAT/OSE validation before delivering to the buyer, even though the regulation technically permits sending first.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Peru' AND ds.sort_order = 6;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🚫 Validity, not just penalties, is the core risk', NULL, NULL, 'A CPE that fails OSE/SUNAT validation simply isn''t a legally valid tax document — this affects the buyer''s ability to deduct the expense or claim VAT credit, which is often a sharper commercial consequence than any administrative fine.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🛰️ Related electronic reporting', NULL, NULL, 'Peru also runs periodic VAT withholding/perception reports (via the comprobantes de retención/percepción within the CPE family) and increasingly channels sector-specific reporting — like the new airline ticket system — through the same electronic infrastructure.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🖥️ SIRE portal', NULL, NULL, 'SUNAT''s official documentation and tools, including the SIRE portal, are the primary reference point for current technical specifications — check there directly for anything not covered by your PSE/OSE provider''s own documentation.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Peru';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '📦 OSE limitations', NULL, NULL, 'Remember that OSEs are not permitted to validate delivery or transport documents in some system configurations — confirm this boundary with your specific provider if your business involves logistics or dispatch guides (GRE).', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Peru' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.sunat.gob.pe', 0 FROM countries WHERE name_en = 'Peru';
